import Database from "better-sqlite3";
import path from "node:path";

// Single sqlite file backing both Better Auth's tables (user, session, account,
// verification) and the read helpers in `users.ts`. Kept as a global singleton
// so Next.js dev-mode hot reloads don't reopen (and re-lock) the file on every
// edit.
const dbPath = process.env.DATABASE_PATH ?? path.join(process.cwd(), "notely.db");

declare global {
  // eslint-disable-next-line no-var
  var __notelyDb: Database.Database | undefined;
}

export const db = globalThis.__notelyDb ?? new Database(dbPath);

if (process.env.NODE_ENV !== "production") {
  globalThis.__notelyDb = db;
}

