import { headers } from "next/headers";
import { auth } from "./auth";
import { db } from "./db";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = {
  id: string;
  email: string;
  name: string | null;
  createdAt: string | number;
};

function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name && row.name.length > 0 ? row.name : row.email,
    createdAt: new Date(row.createdAt).toISOString().slice(0, 10),
  };
}

// Reads go straight against the `user` table that Better Auth (see auth.ts)
// creates and writes to on sign-up / social sign-in — there is no separate
// user store to keep in sync.
export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare(`SELECT id, email, name, createdAt FROM user ORDER BY createdAt ASC`)
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare(`SELECT id, email, name, createdAt FROM user WHERE id = ?`)
    .get(id) as UserRow | undefined;
  return row ? toUser(row) : undefined;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session?.user) return undefined;
  return getUser(session.user.id);
}

