import Database from "better-sqlite3";
import path from "node:path";

// Single sqlite file backing both Better Auth's tables (user, session, account,
// verification) and the read helpers in `users.ts`. Kept as a global singleton
// so Next.js dev-mode hot reloads don't reopen (and re-lock) the file on every
// edit.
const dbPath = process.env.DATABASE_PATH ?? path.join(process.cwd(), "notely.db");

declare global {
  // eslint-disable-next-line no-var
  var __notelyDb: Database.Database | undefined;
}

export const db = globalThis.__notelyDb ?? new Database(dbPath);

if (process.env.NODE_ENV !== "production") {
  globalThis.__notelyDb = db;
}

// Bootstraps Better Auth's default schema (equivalent to `npx @better-auth/cli
// migrate`) so a fresh checkout works with just `npm install && npm run dev`,
// no separate migration step. Safe to run on every boot: CREATE TABLE/INDEX
// IF NOT EXISTS are no-ops once the schema exists.
db.exec(`
  CREATE TABLE IF NOT EXISTS "user" (
    "id" text not null primary key,
    "name" text not null,
    "email" text not null unique,
    "emailVerified" integer not null,
    "image" text,
    "createdAt" date not null,
    "updatedAt" date not null
  );

  CREATE TABLE IF NOT EXISTS "session" (
    "id" text not null primary key,
    "expiresAt" date not null,
    "token" text not null unique,
    "createdAt" date not null,
    "updatedAt" date not null,
    "ipAddress" text,
    "userAgent" text,
    "userId" text not null references "user" ("id") on delete cascade
  );

  CREATE TABLE IF NOT EXISTS "account" (
    "id" text not null primary key,
    "accountId" text not null,
    "providerId" text not null,
    "userId" text not null references "user" ("id") on delete cascade,
    "accessToken" text,
    "refreshToken" text,
    "idToken" text,
    "accessTokenExpiresAt" date,
    "refreshTokenExpiresAt" date,
    "scope" text,
    "password" text,
    "createdAt" date not null,
    "updatedAt" date not null
  );

  CREATE TABLE IF NOT EXISTS "verification" (
    "id" text not null primary key,
    "identifier" text not null,
    "value" text not null,
    "expiresAt" date not null,
    "createdAt" date not null,
    "updatedAt" date not null
  );

  CREATE INDEX IF NOT EXISTS "session_userId_idx" on "session" ("userId");
  CREATE INDEX IF NOT EXISTS "account_userId_idx" on "account" ("userId");
  CREATE INDEX IF NOT EXISTS "verification_identifier_idx" on "verification" ("identifier");
`);
